// A small stand-in for @rbxts/compiler-types, written for these tests. Iterable has one type parameter,
// like the real package, which is what patch 0002 exists for.
interface Array<T> extends ReadonlyArray<T> {
	push(this: Array<T>, ...items: Array<T>): number;
}
interface ReadonlyArray<T> extends Iterable<T> {
	readonly [n: number]: T;
	size(this: ReadonlyArray<T>): number;
}
interface Boolean {}
interface CallableFunction extends Function {}
interface Function {}
interface IArguments {}
interface NewableFunction extends Function {}
interface Number {}
interface Object {}
interface RegExp {}
interface String extends Iterable<string> {
	size(this: string): number;
}
interface TemplateStringsArray extends ReadonlyArray<string> {}
interface Symbol {}
interface SymbolConstructor {
	readonly iterator: unique symbol;
}
declare const Symbol: SymbolConstructor;
interface IteratorResult<T> {
	done?: boolean;
	value: T;
}
interface Iterator<T> {
	next(): IteratorResult<T>;
}
interface Iterable<T> {
	[Symbol.iterator](): Iterator<T>;
}
interface IterableIterator<T> extends Iterator<T> {
	[Symbol.iterator](): IterableIterator<T>;
}
interface ReadonlyMap<K, V> extends Iterable<[K, V]> {
	get(this: ReadonlyMap<K, V>, key: K): V | undefined;
}
interface Map<K, V> extends ReadonlyMap<K, V> {
	set(this: Map<K, V>, key: K, value: V): this;
}
interface MapConstructor {
	new <K, V>(): Map<K, V>;
}
declare const Map: MapConstructor;
interface ReadonlySet<T> extends Iterable<T> {
	has(this: ReadonlySet<T>, value: T): boolean;
}
interface Set<T> extends ReadonlySet<T> {
	add(this: Set<T>, value: T): this;
}
interface SetConstructor {
	new <T>(): Set<T>;
}
declare const Set: SetConstructor;
declare function assert(condition: unknown): asserts condition;
declare function ambientFromTypes(): number;
